// ============================================================
// METHODOLOGY — Flows Governance DPMO Calculation
// Unit: one custom (non-managed-package) Salesforce Flow,
//       identified by NamespacePrefix === null
// Defect Opportunities per unit (3):
//   1. Missing Description  (Description === null)
//   2. No Active Version    (ActiveVersionId === null)
//   3. Stale Active Version (ActiveVersionId !== LatestVersionId,
//                            only checked when ActiveVersionId exists)
// DPMO = (Total Defects / Total Opportunities) x 1,000,000
// Sigma Level = NORMSINV(1 - DPMO/1,000,000) + 1.5
//   (standard 1.5-sigma long-term shift convention)
// Inverse normal CDF implemented via Acklam's algorithm
// (rational approximation, standard reference method —
// no lookup table, no LLM estimation).
// ============================================================

const runContext = $('Initialize Run Context').first().json;
const inputPayload = $input.first().json;
if (!Array.isArray(inputPayload.records)) {
  throw new Error('Salesforce response schema invalid: records must be an array.');
}
const allRecords = inputPayload.records;

// Rule 12 / scoping decision: only in-scope custom flows are
// counted as governance measurement units. Managed-package
// flows are excluded — documented in METHODOLOGY.md.
const inScopeFlows = allRecords.filter(r => r.NamespacePrefix === null);

const OPPORTUNITIES_PER_UNIT = 3;
const totalUnits = inScopeFlows.length;
const totalOpportunities = totalUnits * OPPORTUNITIES_PER_UNIT;

const flowResults = inScopeFlows.map(flow => {
  const defects = [];

  if (flow.Description === null) {
    defects.push({
      check: 'Missing Description',
      detail: 'Flow has no description — fails documentation/discoverability governance.'
    });
  }

  if (flow.ActiveVersionId === null) {
    defects.push({
      check: 'No Active Version',
      detail: 'Flow has a Latest Version but no Active Version — built but never activated, or deactivated.'
    });
  } else if (flow.ActiveVersionId !== flow.LatestVersionId) {
    defects.push({
      check: 'Stale Active Version',
      detail: 'The active version does not match the latest version — live behavior differs from builder state.'
    });
  }

  return {
    apiName: flow.ApiName,
    label: flow.Label,
    processType: flow.ProcessType,
    defectCount: defects.length,
    defects: defects
  };
});

const totalDefects = flowResults.reduce((sum, f) => sum + f.defectCount, 0);
const dpmo = totalOpportunities > 0
  ? (totalDefects / totalOpportunities) * 1000000
  : 0;

// ---- Inverse Normal CDF: Acklam's algorithm ----
// Standard rational approximation for the probit function,
// accurate to ~1.15e-9. Reference: Peter Acklam's public-domain
// algorithm for the inverse of the standard normal CDF.
function inverseNormalCDF(p) {
  if (p <= 0) return -Infinity;
  if (p >= 1) return Infinity;

  const a = [-3.969683028665376e+01, 2.209460984245205e+02, -2.759285104469687e+02,
             1.383577518672690e+02, -3.066479806614716e+01, 2.506628277459239e+00];
  const b = [-5.447609879822406e+01, 1.615858368580409e+02, -1.556989798598866e+02,
             6.680131188771972e+01, -1.328068155288572e+01];
  const c = [-7.784894002430293e-03, -3.223964580411365e-01, -2.400758277161838e+00,
             -2.549732539343734e+00, 4.374664141464968e+00, 2.938163982698783e+00];
  const d = [7.784695709041462e-03, 3.224671290700398e-01, 2.445134137142996e+00,
             3.754408661907416e+00];

  const pLow = 0.02425;
  const pHigh = 1 - pLow;
  let q, r;

  if (p < pLow) {
    q = Math.sqrt(-2 * Math.log(p));
    return (((((c[0]*q+c[1])*q+c[2])*q+c[3])*q+c[4])*q+c[5]) /
           ((((d[0]*q+d[1])*q+d[2])*q+d[3])*q+1);
  } else if (p <= pHigh) {
    q = p - 0.5;
    r = q * q;
    return (((((a[0]*r+a[1])*r+a[2])*r+a[3])*r+a[4])*r+a[5])*q /
           (((((b[0]*r+b[1])*r+b[2])*r+b[3])*r+b[4])*r+1);
  } else {
    q = Math.sqrt(-2 * Math.log(1 - p));
    return -(((((c[0]*q+c[1])*q+c[2])*q+c[3])*q+c[4])*q+c[5]) /
            ((((d[0]*q+d[1])*q+d[2])*q+d[3])*q+1);
  }
}

const dpmoFraction = dpmo / 1000000;
// Guard against p=1 (0 DPMO) which would make inverseNormalCDF return Infinity
const sigmaLevel = dpmoFraction > 0
  ? inverseNormalCDF(1 - dpmoFraction) + 1.5
  : 6.0; // convention: 0 measured defects reported as process ceiling, not infinite

return [{
  json: {
    runId: runContext.runId,
    startedAt: runContext.startedAt,
    workflowVersion: runContext.workflowVersion,
    methodology: {
      unit: 'Custom (non-managed-package) Salesforce Flow, NamespacePrefix === null',
      opportunitiesPerUnit: OPPORTUNITIES_PER_UNIT,
      defectChecks: ['Missing Description', 'No Active Version', 'Stale Active Version'],
      scopingNote: 'Managed-package flows excluded — org admin does not author/control them, so they cannot be a governance defect for this org.'
    },
    measurement: {
      totalFlowsInOrg: allRecords.length,
      inScopeUnits: totalUnits,
      totalOpportunities: totalOpportunities,
      totalDefects: totalDefects,
      dpmo: Math.round(dpmo * 100) / 100,
      sigmaLevel: Math.round(sigmaLevel * 1000) / 1000
    },
    controlChart: {
      status: 'NOT_YET_MEASURABLE',
      reason: 'This is baseline scan #1. I-MR (or any control chart) requires at least 2 time-ordered measurements to calculate a moving range and meaningful control limits. Fabricating limits from a single snapshot would violate measurement validity. Limits will be calculated starting from the second scan.'
    },
    flowDetails: flowResults
  }
}];

