  entry.impact.rationale.trim().length > 0
    ? entry.impact.rationale.trim()
    : 'Human review is required to confirm the business consequence.';

// Defense-in-depth validation.
// A record must be cleanly validated and explicitly routed as Critical.
if (
  entry.validationFlag !== 'OK' ||
  entry.routingDecision !== 'Critical'
) {
  return {
    json: {
      runId,
      storyId: `STORY-${entry.issueId}-FLAGGED`,
      status: 'NOT GENERATED - validation failed or record was misrouted',
      reason:
        entry.validationFlag ||
        'The record did not meet the Critical routing requirements.',
      linkedIssueId: entry.issueId,
      routingDecision: entry.routingDecision,
      note:
        'No Critical user story was generated. The finding must be routed to human review.'
    }
  };
