    }
  }];
}

const movingRanges = [];
for (let i = 1; i < n; i++) {
  movingRanges.push(Math.abs(dpmoValues[i] - dpmoValues[i - 1]));
}

const mean = dpmoValues.reduce((a, b) => a + b, 0) / n;
const mrBar = movingRanges.reduce((a, b) => a + b, 0) / movingRanges.length;

const D2_CONSTANT = 1.128;
const D4_CONSTANT = 3.267;

const sigmaEstimate = mrBar / D2_CONSTANT;
const iChartUCL = mean + 3 * sigmaEstimate;
const iChartLCL = Math.max(0, mean - 3 * sigmaEstimate);
const mrChartUCL = D4_CONSTANT * mrBar;
const mrChartLCL = 0;

const ASQ_CONFIDENCE_THRESHOLD = 20;

