}
const duplicateIds = Object.keys(idCounts).filter((id) => idCounts[id] > 1);
const realIssueIds = new Set(originalIssueLog.map((entry) => entry.issueId));
const unexpectedJudgments = aiJudgments.filter((judgment) => !realIssueIds.has(judgment?.issueId));

const mergedIssueLog = originalIssueLog.map((entry) => {
  const matching = aiJudgments.filter((judgment) => judgment?.issueId === entry.issueId);
  const judgment = matching[0];

  if (!judgment) {
    return {
      ...entry,
      impact: {
        label: 'UNASSIGNED',
        score: null,
        rationale: responseFailure || 'AI judgment missing for this issue.',
        note: 'Human assessment required.'
