  const validationIssues = [];
  const impactValid = ALLOWED_IMPACT.includes(judgment.impact);
  const severityValid = ALLOWED_SEVERITY.includes(judgment.severity);
  const rationaleValid = typeof judgment.impactRationale === 'string'
    && judgment.impactRationale.trim().length >= 10;
  const confidenceValid = typeof judgment.confidence === 'number'
    && Number.isFinite(judgment.confidence)
    && judgment.confidence >= 0
    && judgment.confidence <= 1;

