  if (!severityValid) validationIssues.push('severity invalid');
  if (!rationaleValid) validationIssues.push('impactRationale invalid');
  if (!confidenceValid) validationIssues.push('confidence invalid');
  if (matching.length > 1) validationIssues.push('duplicate judgment');

  const impactScore = impactValid ? IMPACT_SCORE_MAP[judgment.impact] : null;
  const priorityScore = impactScore === null ? null : entry.exposureScore.value * impactScore;

  return {
    ...entry,
    impact: {
      label: impactValid ? judgment.impact : 'INVALID',
      score: impactScore,
      rationale: rationaleValid ? judgment.impactRationale.trim() : 'Human assessment required.'
    },
    severity: severityValid ? judgment.severity : 'INVALID',
    confidence: confidenceValid ? judgment.confidence : null,
    priorityScore,
    validationFlag: validationIssues.length ? validationIssues.join('; ') : 'OK',
    routingDecision: validationIssues.length ? 'Review Required' : judgment.severity
  };
});

