    }

    .pill {
      display: inline-block;
      padding: 4px 9px;
      border-radius: 999px;
      font-size: 12px;
      font-weight: 700;
      white-space: nowrap;
    }

    .critical {
      color: #ff9ca5;
      background: #4b1f27;
    }

    .minor {
      color: #78ead6;
      background: #123c35;
    }

    .review {
      color: #ffe096;
      background: #493d1b;
    }

    .control-grid {
      display: grid;
      grid-template-columns: 1.5fr 1fr 1fr;
      gap: 14px;
    }

    .status {
      color: var(--teal);
      font-weight: 700;
    }

    .formula {
      margin-top: 8px;
      color: var(--muted);
      font-family:
        "SFMono-Regular",
        Consolas,
        monospace;
      font-size: 12px;
    }

    .footer {
      margin-top: 32px;
      padding-top: 18px;
      border-top: 1px solid var(--line);
      color: var(--muted);
      font-size: 12px;
    }

    .footer strong {
      color: var(--white);
    }

    @media (max-width: 900px) {
      .page {
        padding: 22px;
      }

      .metric-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
      }

      .control-grid {
        grid-template-columns: 1fr;
      }

      h1 {
        font-size: 30px;
      }
    }

    @media (max-width: 520px) {
      .metric-grid {
        grid-template-columns: 1fr;
      }
    }

    @media print {
      body {
        color: #111;
        background: #fff;
      }

      .page {
        max-width: none;
        padding: 20px;
      }

      .hero,
      .card,
      table,
      th {
        color: #111;
        background: #fff;
      }

      .subtitle,
      .muted,
      small,
      .footer,
      .formula {
        color: #555;
      }

      .table-container,
      .hero,
      .card {
        border-color: #bbb;
      }

      .metric,
      .brand,
      th,
      .status {
        color: #00796b;
      }

      tbody tr:hover {
        background: transparent;
      }
    }
  </style>
</head>

<body>
  <main class="page">

    <section class="hero">
      <div class="brand">VIRIDIAN INTELLIGENCE</div>

      <h1>Salesforce Governance Sentinel</h1>

      <div class="subtitle">
        Governed agentic analysis
        &bull;
        deterministic Six Sigma measurement
        &bull;
        human-controlled remediation
      </div>

      <div class="run-details">
        Run ID:
        <strong>${escapeHtml(context.runId)}</strong>

        &nbsp; | &nbsp;

        Started:
        ${escapeHtml(context.startedAt)}
      </div>
    </section>

    <section class="metric-grid">
      <div class="card">
        <div class="metric-label">In-scope flows</div>
        <div class="metric">
          ${formatNumber(measurement.inScopeUnits, 0)}
        </div>
      </div>

      <div class="card">
        <div class="metric-label">Governance defects</div>
        <div class="metric">
          ${formatNumber(measurement.totalDefects, 0)}
        </div>
      </div>

      <div class="card">
        <div class="metric-label">Total opportunities</div>
        <div class="metric">
          ${formatNumber(measurement.totalOpportunities, 0)}
        </div>
      </div>

      <div class="card">
        <div class="metric-label">DPMO</div>
        <div class="metric">
          ${formatNumber(measurement.dpmo, 2)}
        </div>
      </div>
    </section>

    <section class="metric-grid">
      <div class="card">
        <div class="metric-label">Sigma level</div>
        <div class="metric">
          ${formatNumber(measurement.sigmaLevel, 3)}
        </div>
      </div>

      <div class="card">
        <div class="metric-label">Critical</div>
        <div class="metric">
          ${formatNumber(findings.criticalCount, 0)}
        </div>
      </div>

      <div class="card">
        <div class="metric-label">Minor</div>
        <div class="metric">
          ${formatNumber(findings.minorCount, 0)}
        </div>
      </div>

      <div class="card">
        <div class="metric-label">Human review</div>
        <div class="metric">
          ${formatNumber(findings.reviewRequiredCount, 0)}
        </div>
      </div>
    </section>

    <div class="notice">
      <strong>Six Sigma measurement statement:</strong>

      DPMO and Sigma are governance defect-density indicators
      based on three declared defect opportunities per custom
      Salesforce Flow.

      These measurements are not Cpk.

      Cpk is intentionally excluded because valid customer
      specification limits have not been established.
    </div>

    <div class="notice governance-notice">
      <strong>Agentic governance statement:</strong>

      AI assigns contextual impact, severity, rationale and confidence.

      AI does not calculate or modify the measured defects,
      DPMO, Sigma level or control-chart limits.

      Invalid, uncertain or inconsistent AI responses are routed
      to human review.
    </div>

    <h2>Governance issue register</h2>

    <div class="table-container">
      <table>
        <thead>
          <tr>
            <th>Issue ID</th>
            <th>Salesforce Flow</th>
            <th>Observed defects</th>
            <th>AI impact assessment</th>
            <th>Severity</th>
            <th>Routing decision</th>
            <th>AI confidence</th>
          </tr>
        </thead>

        <tbody>
          ${
            issueRows ||
            `
              <tr>
                <td colspan="7">
                  No governance defects were detected in this scan.
                </td>
              </tr>
            `
          }
        </tbody>
      </table>
    </div>

    <h2>Statistical process control</h2>

    <section class="control-grid">
      <div class="card">
        <h3>Control-chart status</h3>

        <div class="status">
          ${escapeHtml(chart.status)}
        </div>

        <p class="muted">
          ${escapeHtml(controlChartStatement)}
        </p>
      </div>

      <div class="card">
        <h3>Individuals chart</h3>

        <p>
          Center line:
          <strong>
            ${formatNumber(individualsChart.centerline)}
          </strong>
        </p>

        <p>
          Upper control limit:
          <strong>
            ${formatNumber(individualsChart.ucl)}
          </strong>
        </p>

        <p>
          Lower control limit:
          <strong>
            ${formatNumber(individualsChart.lcl)}
          </strong>
        </p>

        <div class="formula">
          ${escapeHtml(individualsChart.formula)}
        </div>
      </div>

      <div class="card">
        <h3>Moving-range chart</h3>

        <p>
          Center line:
          <strong>
            ${formatNumber(movingRangeChart.centerline)}
          </strong>
        </p>

        <p>
          Upper control limit:
          <strong>
            ${formatNumber(movingRangeChart.ucl)}
          </strong>
        </p>

        <p>
          Lower control limit:
          <strong>
            ${formatNumber(movingRangeChart.lcl)}
          </strong>
        </p>

        <div class="formula">
          ${escapeHtml(movingRangeChart.formula)}
        </div>
      </div>
    </section>

    <div class="footer">
      <p>
        <strong>Data scope:</strong>
        Salesforce Flow metadata only.
        This workflow does not request Salesforce business-record data.
      </p>

      <p>
        <strong>Decision control:</strong>
        AI assessments are advisory.
        Critical actions and all uncertain or invalid outputs require
        human approval.
      </p>

      <p>
        <strong>Traceability:</strong>
        Run ${escapeHtml(context.runId)}
        generated at ${escapeHtml(generatedAt)}.
      </p>
    </div>

  </main>
</body>

</html>`;

return [
  {
    json: {
      runId: context.runId,
      reportStatus: 'HTML_READY',
      suggestedFileName:
        `salesforce-governance-sentinel-${context.runId}.html`,
      mimeType: 'text/html',
      html,
      reportSummary: {
        measurement,
        routing: {
          critical: findings.criticalCount,
          minor: findings.minorCount,
          reviewRequired: findings.reviewRequiredCount
        },
        controlChartStatus: chart.status,
        schemaValidation: findings.finalSchemaValidation
      }
    }
  }
];
